def read_amount():
    while True:
        try:
            raw = input("Amount or cancel: ")
        except EOFError:
            return None
        if raw.strip().lower() == "cancel":
            return None
        try:
            amount = float(raw)
        except ValueError:
            print("Try a number")
            continue
        if amount >= 0 and amount < float("inf"):
            return amount
        print("Use a finite number of 0 or more")

